import 'package:flutter/material.dart';
import 'package:flutter_share/flutter_share.dart';
import 'package:flutter_widget_from_html_core/flutter_widget_from_html_core.dart';

class DescriptionDictionary extends StatelessWidget {
  const DescriptionDictionary({super.key});
 Future<void> share() async {
    await FlutterShare.share(
      title: "وصـف المـعـجـم",
      text:'وصف المعجم كتاب "المعرَّب من الكلام الأعجمي على حروف المعجم" لأبي منصور موهوب بن أحمد الجواليقي (465هـ – 540هـ) من أهم المراجع في بابه. فإن الألفاظ الأعجمية التي دخلت في اللغة العربية عبر العصور، وجرت على ألسنة الفصحاء، كانت مبثوثة في كتب اللغة، فجاء أبو منصور، وجمعها في كتاب مفرد، ورتّبها على حروف المعجم، فكان كتابه أكبر كتاب في ذلك العصر. طبع كتاب المعرب مرتين من قبل. طبعه أولاً المستشرق الألماني إدورد زخاو، وصدرت طبعته في ليبزيك سنة 1867م مذيّلة بتعليقاته بالألمانية. ثمّ حقّقه المحدّث الكبير الأستاذ أحمد محمد شاكر رحمه الله عن عدّة نسخ تحقيقًا جيدًا. وظهرت النشرة الثانية سنة 1942م بالقاهرة. وصدر الكتاب، عن دار القلم بدمشق، في طبعة جديدة أنيقة، تختلف عن الطبعتين السابقتين في طبيعتها، وتفوّقهما في جمالها وروعتها، فهي ليست تحقيقًا جديدًا لكتاب المعرب بالمعنى الاصطلاحي المحدث، فإنّ عمل المحقّق أن يجتهد في إخراج النص، كما صدر عن مؤلّفه، سليمًا من آفات التصحيف والتحريف، ليعتمد عليه العلماء والباحثون في دراساتهم المختلفة؛ وكان الأستاذ أحمد شاكر قد فرغ من ذلك في نشرته، وكانت الطبعة الخامسة 2020م بتحقيقه أحمد شاكر نشرت من طرف دار الكتب والوثائق القومية بالقاهرة مصر.  المصدر: ينظر: محمد أجمل الإصلاحي، كتاب بحوث ومقالات في اللغة والأدب وتقويم النصوص، دار الغرب الإسلامي، بيروت، لبنان، ط1، 2007م، ص: 423.  وقال فيه الدكتور أحمد عزام " كتاب المعرّب من الكلام الأعجمي لأبي منصور موهوب بن أحمد الجواليقي أجمع ما عرفنا من الكتب التي ضبطت الألفاظ المعرّبة. جمع فيه مؤلفه ما عرب من الألفاظ الأعجمية إلى عصره وحرص على أن يبين اللغات التي أخذت منها الألفاظ، وأصول الألفاظ في هذه اللغات ما وسعه علمه، كما اجتهد أن يسند الأقوال إلى أصحابها من أئمة اللغة. ولم يأل جهدا في الاستشهاد بالآيات والأحاديث والشعر. ورتب ما جمع على حروف المعجم، تيسيرا للمستفيد".  المصدر: مقدمة بقلم الدكتور عبد الوهاب عزام من كتاب الجواليقي، المعرّب من الكلام الأعجمي على حروف المعجم، تح: أحمد محمد شاكر، مطبعة دار الكتب والوثائق القومية، القاهرة، مصر، ط5، 2020م، ص 03.',
    );
  }
